'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/payouts — disburse Mobile Money to a recipient (transfers out).
 */
class Payouts {
  constructor(client) {
    this.client = client;
  }

  /**
   * List payouts.
   * @param {object} [params] Query params (e.g. page, limit, status)
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/payouts', params));
  }

  /**
   * Retrieve a payout by reference.
   * @param {string} reference
   */
  retrieve(reference) {
    return this.client.request('GET', `/v1/payouts/${encodeURIComponent(reference)}`);
  }

  /**
   * Get just the status of a payout.
   * @param {string} reference
   */
  status(reference) {
    return this.client.request('GET', `/v1/payouts/${encodeURIComponent(reference)}/status`);
  }

  /**
   * Create a payout (send money to a Mobile Money recipient).
   * @param {object} params
   * @param {number} params.amount           100–2,000,000
   * @param {string} params.currency         e.g. "XOF"
   * @param {string} params.operator_code    e.g. "ORANGE_MONEY_CI", "MTN_MONEY_CI", "FLOOZ_MONEY_CI", "WAVE_MONEY_CI"
   * @param {string} params.external_ref     Your own idempotent reference
   * @param {object} [params.recipient]      { phone, phone_prefix, first_name, last_name, ... }
   * @param {string} [params.recipient_phone] Legacy/simple alternative to `recipient`
   * @param {string} [params.note]
   */
  create(params) {
    return this.client.request('POST', '/v1/payouts', params);
  }
}

module.exports = Payouts;
